        },
      });
    }

    if (action === 'delete') {
      const providerId = typeof body.providerId === 'string' ? body.providerId.trim() : '';
      if (!getProviderDefinition(providerId)) {
        return jsonResponse(request, { status: 'error', message: 'Unbekannter Provider.' }, 400);
