      const deleteResponse = await serviceFetch(
        config,
        `/rest/v1/user_ai_provider_credentials?user_id=eq.${encodeURIComponent(userId)}&provider_id=eq.${encodeURIComponent(providerId)}`,
        { method: 'DELETE' },
